def align_scores(a,b,bg=3):
    # b shift dy,dx relative a
    out=[]
    for dy in range(-b.shape[0]+1,a.shape[0]):
      for dx in range(-b.shape[1]+1,a.shape[1]):
        matches=conf=union=0
        for y in range(b.shape[0]):
          for x in range(b.shape[1]):
            ay=y+dy; ax=x+dx
            if 0<=ay<a.shape[0] and 0<=ax<a.shape[1]:
              av=a[ay,ax];bv=b[y,x]
              if av!=bg and bv!=bg:
                if av==bv:matches+=1
                else:conf+=1
        if matches and conf==0:out.append((matches,dy,dx))
    return sorted(out,reverse=True)
